INSERT OR IGNORE INTO purchases(session_id,owner,payment_id,status,amount,credits,created_at) SELECT 'testing-grant-2026-10-12-1000','6e8bc3fc-4b35-47f4-bdea-b175ca1c4477',NULL,'paid',0,1000,unixepoch() FROM principals WHERE id='6e8bc3fc-4b35-47f4-bdea-b175ca1c4477' AND google_sub='107038734643938960197';
INSERT OR IGNORE INTO ledger(owner,kind,amount,pool,business_key,payment_id,created_at) SELECT owner,'grant',credits,'paid','purchase:'||session_id,session_id,unixepoch() FROM purchases WHERE session_id='testing-grant-2026-10-12-1000' AND owner='6e8bc3fc-4b35-47f4-bdea-b175ca1c4477' AND status='paid';
INSERT INTO audit(kind,object_id,detail,created_at) SELECT 'testing-credit-grant',session_id,'User requested 1000 complimentary credits for testing; no payment charged.',unixepoch() FROM purchases WHERE session_id='testing-grant-2026-10-12-1000' AND NOT EXISTS (SELECT 1 FROM audit WHERE kind='testing-credit-grant' AND object_id='testing-grant-2026-10-12-1000');
